<?php if(!defined('ABSPATH'))exit;$d=woogit_portal_data();get_header();if(!$d['authenticated']){woogit_render_status('error','نشست شما منقضی شده است.');get_footer();return;}$s=$d['site'];$url=woogit_portal_value($s,['url','site_url','domain'],'—');$rawStatus=woogit_portal_value($s,['status','connection_status','verification_status'],'نامشخص');$status=woogit_portal_status($rawStatus);?><section class="wg-section wg-portal"><div class="wg-container"><div class="wg-section__head"><div><span class="wg-eyebrow">Connected Site</span><h1>فروشگاه متصل</h1><p>اطلاعات اتصال از Backend authoritative می‌آید؛ Theme به فروشگاه مشتری متصل نمی‌شود.</p></div></div><div class="wg-card wg-card--featured"><span>آدرس فروشگاه</span><h2 dir="ltr"><?php echo woogit_safe_text($url); ?></h2><p>وضعیت اتصال: <span class="wg-status wg-status--<?php echo esc_attr($status[1]); ?>"><?php echo woogit_safe_text($status[0]); ?></span></p></div><div class="wg-grid wg-grid--2"><article class="wg-card"><span>شناسه سایت</span><strong><?php echo woogit_safe_text(woogit_portal_value($s,['site_id','id'],'—')); ?></strong></article><article class="wg-card"><span>آخرین وضعیت</span><strong><?php echo woogit_safe_text(woogit_portal_value($s,['updated_at','last_checked_at'],'—')); ?></strong></article></div></div></section><?php get_footer(); ?>